"""Report source-preserving existing-data joint FSS and predictive checks."""
import os
for k in ['OPENBLAS_NUM_THREADS','OMP_NUM_THREADS','NUMBA_NUM_THREADS']:os.environ[k]='1'
os.environ['MPLBACKEND']='Agg';os.environ.setdefault('MPLCONFIGDIR','/private/tmp/luscher-joint-fss-report')
from pathlib import Path
import json,csv,hashlib,shutil,time
import numpy as np
import matplotlib.pyplot as plt
OUT=Path(__file__).resolve().parent
MAIN=OUT/'joint-fss-existing-20261016-full';SAM=OUT/'joint-fss-sampling-checks-20261016-v2';POST=OUT/'joint-fss-posthoc-diagnostics-20261016'

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(p,a):p.write_text(json.dumps(a,indent=2,allow_nan=False)+'\n')
def main():
    folder=OUT/'joint-fss-existing-delivery-20261016';folder.mkdir(exist_ok=False)
    sources=[MAIN,SAM,POST];all_results=[]
    for parent in sources:
        a=json.loads((parent/'analysis.json').read_text())
        for r in a['results']:r=dict(r);r['source_folder']=str(parent);all_results.append(r)
    results={r['config']['name']:r for r in all_results}
    original={r['config']['name']:r for r in all_results if Path(r['source_folder'])==MAIN}
    # Same-bank/draw contrasts only. Never pair cut/block/start-parity variants.
    pairs=[('inner-min12-mixed','inner-min12-leading'),('inner-min16-leading','inner-min12-leading'),('inner-min24-leading','inner-min12-leading'),('inner-min12-second','inner-min12-leading'),('inner-min12-cubic','inner-min12-leading'),('inner-min12-raw-background','inner-min12-raw-zero-background')]
    contrasts=[]
    for a,b in pairs:
        ra,rb=original[a],original[b];da=np.load(MAIN/(a+'-draws.npz'))['parameters'][:,1];db=np.load(MAIN/(b+'-draws.npz'))['parameters'][:,1];mask=np.isfinite(da)&np.isfinite(db);d=da[mask]-db[mask]
        contrasts.append(dict(first=a,second=b,central_shift=ra['central']['Delta']-rb['central']['Delta'],paired_statistical_SD=float(np.std(d,ddof=1)),paired_MC95=np.quantile(d,[.025,.975]).tolist(),common_draws=int(mask.sum()),draws_total=len(da),scope='Same original shared bootstrap draws; estimator/model difference, not a bias relative to the unknown CFT value or a systematic-error confidence bound.'))
    write(folder/'paired-model-differences.json',contrasts)
    with (folder/'joint-fit-summary.csv').open('w') as f:
        w=csv.writer(f);w.writerow(['configuration','window','minimum_L','maximum_L','Delta','stat_SD','MC95_low','MC95_high','qc','qc_stat_SD','training_p','heldout_p_nominal','heldout_max_abs_R','heldout_max_fractional_m2','status','flags','source_folder'])
        for r in all_results:
            c=r['config'];z=r['central'];hi=r.get('heldout',{});w.writerow([c['name'],c['window'],c['minimum'],c['maximum'],z['Delta'],r['parameter_SD'][1],*r['parameter_MC95'][1],z['qc'],r['parameter_SD'][0],z['p'],hi.get('nominal_p'),hi.get('max_abs_R'),hi.get('max_abs_fractional_m2'),r['status'],';'.join(r['flags']),r['source_folder']])
    def save(fig,name):
        fig.savefig(folder/(name+'.png'),dpi=180,bbox_inches='tight');fig.savefig(folder/(name+'.svg'),bbox_inches='tight');plt.close(fig)
    plt.rcParams.update({'font.size':10,'axes.grid':True,'grid.alpha':.2})
    selection=[('inner-min12-leading','Inner: leading correction, L≥12'),('inner-min12-mixed','Inner: mixed thermal/correction terms'),('inner-min12-analytic','Inner: analytic amplitude drift'),('inner-min12-cubic','Inner: cubic thermal response'),('inner-min16-leading','Inner: leading correction, L≥16'),('inner-min24-leading','Inner: leading correction, L≥24'),('inner-min12-second','Inner: additional L^-2ω correction'),('inner-min12-raw-zero-background','Raw m²: no regular background'),('inner-min12-raw-background','Raw m²: regular B/L³ background'),('inner-raw-background-min16','Raw background, L≥16 [follow-up]'),('inner-raw-background-min24','Raw background, L≥24 [follow-up]'),('broad-cubic-max64','Broad cubic response [follow-up]')]
    fig,ax=plt.subplots(figsize=(11,7.7))
    for i,(name,label) in enumerate(selection):
        r=results[name];v=r['central']['Delta'];lo,hi=r['parameter_MC95'][1];color='#ad641f' if r.get('post_hoc') else '#2a668e';ax.errorbar(v,i,xerr=[[v-lo],[hi-v]],fmt='o',color=color,capsize=3)
    ax.axvline(.519088,color='gray',ls='--',lw=1,label='O(2) bootstrap reference (not imposed)');ax.set_yticks(range(len(selection)),[v[1] for v in selection]);ax.invert_yaxis();ax.set_xlabel(r'$\Delta$ (conditional 2,000-draw MC95)');ax.set_title('3D β=0: joint critical-coupling / magnetization fits\nCorrection and background dependence remains unresolved');ax.legend(loc='lower right',fontsize=8);fig.text(.5,.01,'Same MC data; intervals condition on each scaling model. Orange: explicitly post-hoc checks. These are not systematic error bars.',ha='center',fontsize=8);fig.tight_layout(rect=[0,.035,1,1]);save(fig,'01-joint-fit-model-sensitivity')
    fig,axes=plt.subplots(2,2,figsize=(11.5,7),sharex='col')
    for col,window in enumerate(['inner','broad']):
        names=[f'{window}-train12to48-leading',f'{window}-train12to48-mixed']+(['broad-cubic-max48'] if window=='broad' else [])
        for j,name in enumerate(names):
            r=results[name];h=r['heldout'];base=json.loads((MAIN/'input-groups.json').read_text());indices=h['coordinate_indices'];q=np.array([base[i]['q'] for i in indices]);res=np.array(h['observed_minus_predicted']);sd=np.array(h['predictive_SD']);color=['#21618c','#b56824','#298265'][j];label=('Cubic [post-hoc]' if 'cubic' in name else r['config']['model'].capitalize())+f", nominal p={h['nominal_p']:.3g}";dx=(j-.5)*.000004
            axes[0,col].errorbar(q+dx,res[:,0],yerr=sd[:,0],fmt='o',capsize=2,color=color,label=label)
            val=100*np.expm1(res[:,1]);low=100*np.expm1(res[:,1]-sd[:,1]);high=100*np.expm1(res[:,1]+sd[:,1]);axes[1,col].errorbar(q+dx,val,yerr=np.array([val-low,high-val]),fmt='o',capsize=2,color=color)
        axes[0,col].set_title(window.capitalize()+' measured window; train L≤48, test L=64');axes[0,col].legend(fontsize=8);axes[1,col].set_xlabel(r'$q=\epsilon/\pi$');axes[1,col].ticklabel_format(axis='x',style='plain',useOffset=False);axes[0,col].set_ylabel('Observed - predicted ξ/L');axes[1,col].set_ylabel('Observed / predicted m² - 1 (%)')
        for a in axes[:,col]:a.axhline(0,color='black',lw=.8)
    fig.suptitle('Existing-data held-out-size prediction challenge');fig.text(.5,.01,'Bars: ±1 predictive SD, including training-fit and held-out measurement uncertainty. Full joint covariance used for nominal χ².\nCubic follow-up was chosen after the quadratic miss and is not independent validation.',ha='center',fontsize=8);fig.tight_layout(rect=[0,.065,1,.97]);save(fig,'02-heldout-size-predictions')
    labels=['Mixed term - leading','Minimum L16 - L12','Minimum L24 - L12','Second correction - leading','Cubic thermal - quadratic','Regular background - zero background']
    fig,ax=plt.subplots(figsize=(10,5))
    for i,r in enumerate(contrasts):
        v=r['central_shift'];lo,hi=r['paired_MC95'];ax.errorbar(v,i,xerr=[[v-lo],[hi-v]],fmt='o',color='#a45330' if i==5 else '#2a668e',capsize=3)
    ax.set_yticks(range(len(labels)),labels);ax.invert_yaxis();ax.axvline(0,color='black',lw=.8);ax.set_xlabel('Change in fitted Δ (paired conditional MC95)');ax.set_title('Model shifts versus statistical noise\nShared bootstrap draws account for covariance of the two estimators');fig.text(.5,.01,'A difference between estimators does not establish either estimator’s bias or a systematic standard deviation.',ha='center',fontsize=8);fig.tight_layout(rect=[0,.04,1,1]);save(fig,'03-paired-model-shifts')
    # Full reproducible model/prediction data stay in fixed source folders.
    totals=dict(configurations=len(all_results),refits=sum(r['bootstrap_draws'] for r in all_results),successful_refits=sum(r['successful_draws'] for r in all_results),boundary_events=sum(r['boundary_draws'] for r in all_results),multiple_minimum_events=sum(r['multiple_minima_draws'] for r in all_results))
    write(folder/'analysis.json',dict(created=time.time(),results=all_results,paired_model_differences=contrasts,totals=totals,source_hashes={str(p/'analysis.json'):sha(p/'analysis.json') for p in sources},scope='Existing data only. Critical coupling fitted jointly with Delta. All MC intervals conditional; model spread not sigma_sys. Post-hoc curvature/background size checks explicitly separated. No new simulations or modified MC histories.'))
    src=json.loads((MAIN/'sources.json').read_text());ids={i for g in json.loads((MAIN/'input-groups.json').read_text()) for i in g['ids']};points={v['id']:v['point'] for v in src['source_jobs']};chainlength={}
    for i in ids:chainlength[points[i]['steps']]=chainlength.get(points[i]['steps'],0)+1
    sampling=json.loads((SAM/'analysis.json').read_text())['results'];lines=[]
    lines += ['3D beta=0: existing-data joint finite-size scaling analysis','16 October 2026','', 'OUTCOME','The new analysis propagates critical-epsilon uncertainty and demonstrates a specific background/correction ambiguity. It does NOT establish a calibrated systematic standard deviation. No new simulations were launched.','',f'Input bank: 48 coordinate groups, {len(ids)} independently seeded chains, L=12,16,24,32,48,64, q=.8005 through .8015. Chain lengths: {chainlength}; full source-pinned parent cohort has270 trajectories. Narrow window .800625:.801000 uses24 groups/48 chains. Source means/joint bootstrap caches are unchanged.','', 'MODEL AND STATISTICS','Fit R=xi/L and log<m2> jointly. ell=L/32, x=1000(q-qc)*ell^(1/nu), u=ell^-omega.','Baseline R=Rstar+r1*x+r2*x^2+bR*u.','Baseline log<m2>=a-2*Delta*log(ell)+m1*x+m2*x^2+bm*u.','The two responses share qc. Rstar and Delta are free; no critical R or Delta target imposed.','nu=.67169 and omega=.789 are explicitly Wilson-Fisher-informed assumptions. Separate nu=.63/.71, omega=.6/1 stress checks are descriptive, not confidence ranges.','Variant terms: x*u in both observables; analytic thermal amplitude in logm2; u^2; cubic x^3. Raw-m2 variants fit exp(singular log response)+Bphysical/L^3, with signed background and analytic Jacobian.','Profile qc on q=.80025:.80175; globally scan/refine its minima and solve remaining linear GLS coefficients. Full nonlinear raw fits use12 central starting points. Joint rank/conditioning, optimizer success, boundary hits and nonphysical failures are checked on each bootstrap draw.','Within-coordinate 2x2 covariance retained, different independently sampled coordinates treated independent. Fixed central whitening and original joint bootstrap draws reused across all model/size fits. No noisy cross-coordinate sample covariance is used for weighting.','Baseline: cut1001, block factor2, 2000 draws. Separate saved latecut4001, block factor4 and even/odd-start banks are fitted as sampling checks. Across-bank differences are descriptive, not paired significance tests.','', 'SELECTED CONDITIONAL RESULTS (statistical SD, not total error)']
    for name in ['inner-min12-leading','inner-min12-mixed','inner-min16-leading','inner-min24-leading','inner-min12-second','inner-min12-raw-zero-background','inner-min12-raw-background']:
        r=results[name];z=r['central'];lines.append(f"{name}: Delta={z['Delta']:.6f} +/- {r['parameter_SD'][1]:.6f} stat; MC95={r['parameter_MC95'][1]}; qc={z['qc']:.9f} +/- {r['parameter_SD'][0]:.9f}; training nominal p={z['p']:.4g}; flags={r['flags']}")
    lines += ['', 'SYSTEMATIC SHIFT OR STATISTICAL NOISE?','The following differences use matched original bootstrap draws (all2000 common); no independent-error approximation. They measure changes between estimators, not deviation from an unknown true value.']
    for r in contrasts:lines.append(f"{r['first']} minus {r['second']}: central shift {r['central_shift']:+.6f}, paired statSD {r['paired_statistical_SD']:.6f}, paired MC95 {r['paired_MC95']}.")
    bg=results['inner-min12-raw-background'];z=bg['central'];Bphysical=z['background_coefficient']*.033*32**3
    lines += ['',f'The regular-background coefficient corresponds to Bphysical={Bphysical:.4f}, i.e. Bphysical/L^3 in <m2>. This term is allowed because <m2> integrates correlations including short separations. Its fitted fraction is about8.5% atL12,1.2% atL32,0.3% atL64 (conditional on this model). Small corrections can mimic a different exponent over a finite size range. Signed analytic backgrounds are not removed by an arbitrary sign/O(1) prior.','The observed size-cut and second-correction shifts remain statistically compatible with zero in these paired tests. They cannot themselves be declared measured biases. The regular-background estimator shift is conditionally resolved in this family, but this does not prove the model is the true asymptotic form or define sigma_sys.','', 'HELD-OUT-SIZE CHALLENGE','Predeclared training max48 predicts64, and training max32 predicts48/64. Full residual covariance includes shared training-parameter uncertainty plus independent held-out measurement covariance. Nominal Gaussian chi-square diagnostics are descriptive; all sizes/windows were already examined in earlier work, so this is not a prospective blinded experiment.']
    for r in all_results:
        if 'heldout' in r:
            h=r['heldout'];lines.append(f"{r['config']['name']}: testL={h['sizes']}, chi2/dof={h['chi2']:.3f}/{h['dof']}, nominal p={h['nominal_p']:.6g}, maxabs R error={h['max_abs_R']:.6f}, max m2 relative error={100*h['max_abs_fractional_m2']:.3f}%, fitflags={r['flags']}; posthoc={r.get('post_hoc',False)}.")
    lines += ['', 'EXPLORATORY FOLLOW-UP','After observing broad-window quadratic prediction misses, adding cubic thermal responses reduces the test64 discrepancy (nominal p=.134). The full broad cubic estimate is Delta=.52016 +/- .00509stat. This is a post-hoc diagnosis consistent with Taylor-window truncation, not proof of its unique cause or independent validation.','Post-hoc raw-background size-cut fits remain near .55 but weaken: minL16 .55354 +/- .03060stat, minL24 .55164 +/- .04879stat. Dropping smaller boxes does not make the existing data constrain the background tightly.','', 'SAMPLING CHECKS']
    for r in sampling:lines.append(f"{r['config']['name']}: Delta={r['central']['Delta']:.6f} +/- {r['parameter_SD'][1]:.6f}stat; flags={r['flags']}; inputflags={r['input_flags']}.")
    lines += ['', 'WHAT CAN BE CLAIMED','A narrow-window leading joint fit gives Delta=.5182 +/- .0069stat, compatible with prior quotient/slope illustrations near.52. This is a conditional estimate, not the final CFT dimension with total uncertainty.','Critical-epsilon uncertainty is now propagated rather than fixed, but regular-background/correction freedom remains a practical ambiguity. A small numerical sigma_sys or two reliable CFT digits have not been established. No model is selected by best residual p or forced to the known O(2) benchmark.','Next leverage would come from a larger size or an observable less exposed to short-distance background; this report does not authorize or launch either. Larger predictive p alone does not validate a model or set systematic coverage.','', 'VALIDATION AND PRESERVATION',f'{totals}. These are bootstrap refits, not new independent MC experiments.','Two inner train<=32 configurations have boundary/multiple-profile-minimum flags and remain diagnostic; do not equate finite/rank-success with accepted inference. Input low-block/start/half flags remain in input-groups and source analyses.','15 focused synthetic/GLS/Jacobian/rank/heldout/immutable-output tests pass. Numerical simulation kernels, data archives, source histories and old analyses were not modified. A failed sampling-driver attempt due to a cache-path issue remains preserved; v2 completes all12 planned checks without new simulations.','Independent scientific review is recorded separately before final acceptance.','', 'FILES','joint-fit-summary.csv: every fit, statistical interval, diagnostic status and prediction error.','paired-model-differences.json: correlated estimator shifts.','analysis.json: full saved model/prediction diagnostics and source hashes.','01/02/03 PNG/SVG figures: model sensitivity, held-out predictions, paired shifts.','Source folders contain input bank, all coefficients, 2000 parameter draws, covariance matrices, pinned source-job/cache hashes, full logs and frozen implementation.']
    (folder/'joint-finite-size-analysis-report.txt').write_text('\n'.join(lines)+'\n');shutil.copyfile(__file__,folder/Path(__file__).name);write(folder/'delivery-status.json',dict(status='pending_independent_scientific_and_visual_review'))
    print(folder,flush=True)
if __name__=='__main__':main()
